import { supabase } from './supabase';

/**
 * Fetch hazards and their consequences by event ID.
 */
export async function getHazardsByEventId(eventId) {
  try {
    const { data: hazards, error } = await supabase
      .from('hira_hazards')
      .select(`
        id,
        description,
        hira_consequences (
          id,
          description,
          current_controls
        )
      `)
      .eq('event_id', eventId)
      .order('created_at', { ascending: true });

    if (error) {
      console.error('Error fetching hazards:', error);
      throw error;
    }

    return hazards.map(hazard => ({
      hazard_id: hazard.id,
      description: hazard.description,
      consequences: hazard.hira_consequences.map(consequence => ({
        consequence_id: consequence.id,  // Use consistent naming
        description: consequence.description,
        current_controls: consequence.current_controls,  // Use consistent naming
      }))
    }));
  } catch (error) {
    console.error('Error getting hazards:', error);
    throw error;
  }
}

/**
 * Update hazards and their consequences for a specific event.
 */
export async function saveHazardIdentification(projectId, eventsData) {
  try {
    // Process each event
    for (const event of eventsData) {
      // Create new event
      const { data: newEvent, error: eventError } = await supabase
        .from('hira_events')
        .insert({
          project_id: projectId,
          name: event.name,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString()
        })
        .select()
        .single();

      if (eventError) throw eventError;

      // Process hazards for this event
      for (const hazard of event.hazards) {
        // Create new hazard
        const { data: newHazard, error: hazardError } = await supabase
          .from('hira_hazards')
          .insert({
            event_id: newEvent.id,
            description: hazard.description,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
          })
          .select()
          .single();

        if (hazardError) throw hazardError;

        // Process consequences for this hazard
        for (const consequence of hazard.consequences) {
          // Create new consequence
          const { data: newConsequence, error: consequenceError } = await supabase
            .from('hira_consequences')
            .insert({
              hazard_id: newHazard.id,
              description: consequence.description,
              current_controls: consequence.current_controls,
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString()
            })
            .select()
            .single();

          if (consequenceError) throw consequenceError;

          // Create empty risk assessment
          const { error: assessmentError } = await supabase
            .from('hira_risk_assessments')
            .insert({
              consequence_id: newConsequence.id,
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString()
            });

          if (assessmentError) throw assessmentError;
        }
      }
    }

    return true;
  } catch (error) {
    console.error('Error saving hazard identification:', error);
    throw error;
  }
}

export async function updateHazards(eventId, hazardsData) {
  try {
    // Fetch existing hazards with their consequences for the event
    const { data: existingHazards, error: fetchError } = await supabase
      .from('hira_hazards')
      .select(`
        id,
        description,
        hira_consequences (
          id,
          description,
          current_controls
        )
      `)
      .eq('event_id', eventId);

    if (fetchError) throw fetchError;

    // Create a map of existing hazards and consequences
    const existingHazardMap = new Map(existingHazards?.map(h => [h.description, h]) || []);

    // Process each hazard
    const hazardPromises = hazardsData.map(async hazard => {
      const { data: createdHazard, error: hazardError } = await supabase
        .from('hira_hazards')
        .insert({
          event_id: eventId,
          description: hazard.description,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .select()
        .single();

      if (hazardError) {
        console.error('Error creating hazard:', hazardError);
        throw hazardError;
      }

      // Insert consequences and create empty risk assessments
      const consequencePromises = hazard.consequences.map(async consequence => {
        // First create the consequence
        const { data: createdConsequence, error: consequenceError } = await supabase
          .from('hira_consequences')
          .insert({
            hazard_id: createdHazard.id,
            description: consequence.description,
            current_controls: consequence.current_controls,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          })
          .select()
          .single();

        if (consequenceError) throw consequenceError;

        // Then create an empty risk assessment with the consequence_id
        const { error: assessmentError } = await supabase
          .from('hira_risk_assessments')
          .insert({
            consequence_id: createdConsequence.id,  // Link to the just-created consequence
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
          });

        if (assessmentError) {
          console.error('Error creating risk assessment:', assessmentError);
          throw assessmentError;
        }

        console.log('Created consequence and risk assessment:', {
          consequence_id: createdConsequence.id,
          description: createdConsequence.description
        });

        return {
          consequence_id: createdConsequence.id,
          description: createdConsequence.description,
          currentControls: createdConsequence.current_controls,
        };
      });

      const consequences = await Promise.all(consequencePromises);

      return {
        hazard_id: createdHazard.id, // Use hazard_id consistently
        description: createdHazard.description,
        consequences,
      };
    });

    const results = await Promise.all(hazardPromises);
    return results.map(hazardResult => ({
      hazard_id: hazardResult.hazard_id,
      description: hazardResult.description,
      consequences: hazardResult.consequences.map(consequence => ({
        consequence_id: consequence.id,
        description: consequence.description,
        currentControls: consequence.currentControls,
      })),
    }));
  } catch (error) {
    console.error('Error updating hazards:', error);
    throw error;
  }
}

/**
 * Delete all hazards and their consequences for a specific event.
 */
export async function deleteHazards(eventId) {
  try {
    const { error } = await supabase
      .from('hira_hazards')
      .delete()
      .eq('event_id', eventId);

    if (error) throw error;
  } catch (error) {
    console.error('Error deleting hazards:', error);
    throw error;
  }
}
